mapper.select:
	SELECT APPLICANT_ID
	FROM APPLICANT
	WHERE USER_ID = #{userId}
    AND RECRUITMENT_NO = #{recruitmentNo}

mapper.insert:

    SELECT
        'APPL'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(APPLICANT_ID), LENGTH('APPL' ) + 1)), 0) + 1, 6, '0')
    FROM APPLICANT

	INSERT INTO APPLICANT (
		APPLICANT_ID
		, RECRUITMENT_NO
		, RESUME_NO
		, RESUME_VIEW_YN
		, USER_ID
	) VALUES (
		#{applicantId}
		, #{recruitmentNo}
		, #{resumeNo}
		, 'N'
		, #{userId}
	)

mapper.update:
UPDATE APPLICANT SET 
	RESUME_VIEW_YN = 'Y'
WHERE APPLICANT_ID = #{applicantId}

mapper.delete:
UPDATE APPLICANT SET 
	APPLICANT_DEL_DATE = SYSDATE 
WHERE APPLICANT_ID = #{applicantId}
